<?php
declare(strict_types=1);session_start();
const DB=__DIR__.'/../data/store.json';
function db():array {return json_decode(file_get_contents(DB),true)?:[];}
function save(array $d):void{$f=fopen(DB.'.lock','c');flock($f,LOCK_EX);file_put_contents(DB,json_encode($d,JSON_UNESCAPED_UNICODE|JSON_PRETTY_PRINT),LOCK_EX);flock($f,LOCK_UN);fclose($f);}
function reply($data,int $code=200):never{http_response_code($code);header('Content-Type: application/json; charset=utf-8');echo json_encode($data,JSON_UNESCAPED_UNICODE);exit;}
function user(array $d):?array{foreach($d['users'] as $u)if(($u['id']??'')===($_SESSION['uid']??''))return $u;return null;}
function progress(array $d,string $id):int{$a=array_filter($d['checks'],fn($x)=>$x['user']===$id&&$x['done']);return min(100,(int)round(count($a)/21*100));}
function achievements(array $d,string $id):array{$n=count(array_filter($d['checks'],fn($x)=>$x['user']===$id&&$x['done']));$out=[];foreach([1=>'🌱',7=>'⚡',10=>'🎯',14=>'📅',21=>'🏆'] as $days=>$emoji)$out[]=['days'=>$days,'emoji'=>$emoji,'unlocked'=>$n>=$days];return $out;}
function teamProgress(array $d,string $team):int{$members=array_values(array_filter($d['users'],fn($u)=>($u['team']??'')===$team&&$u['role']!=='admin'));if(!$members)return 0;return (int)round(array_sum(array_map(fn($u)=>progress($d,$u['id'])>=50?progress($d,$u['id']):0,$members))/count($members));}
function view(array $d):array{$u=user($d);$teams=[];foreach($d['teams'] as $t)$teams[]=['name'=>$t,'progress'=>teamProgress($d,$t)];usort($teams,fn($a,$b)=>$b['progress']<=>$a['progress']);$people=array_map(function($x)use($d){unset($x['password']);$x['progress']=progress($d,$x['id']);$x['achievements']=achievements($d,$x['id']);return $x;},$d['users']);$mine=array_values(array_filter($d['checks'],fn($x)=>$x['user']===$u['id']));$metrics=array_values(array_filter($d['metrics'],fn($x)=>$x['user']===$u['id']));return ['me'=>array_values(array_filter($people,fn($x)=>$x['id']===$u['id']))[0],'users'=>$people,'teams'=>$teams,'checks'=>$mine,'metrics'=>$metrics,'experts'=>$d['experts'],'notices'=>$d['notices'],'season'=>$d['season'],'draw'=>$d['draw']];}
if(str_starts_with($_SERVER['REQUEST_URI'],'/api/')){$action=trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/');$action=substr($action,4);$d=db();$input=json_decode(file_get_contents('php://input'),true)?:[];if($action==='login'){$u=null;foreach($d['users'] as $x)if($x['login']===($input['login']??'')&&password_verify($input['password']??'',$x['password'])){$u=$x;break;}if(!$u)reply(['error'=>'Неверный логин или пароль'],401);session_regenerate_id(true);$_SESSION['uid']=$u['id'];reply(view($d));}if($action==='logout'){session_destroy();reply(['ok'=>true]);}if(!user($d))reply(['error'=>'Требуется вход'],401);$me=user($d);if($action==='state')reply(view($d));if($_SERVER['REQUEST_METHOD']!=='POST')reply(['error'=>'Метод не поддерживается'],405);
if($action==='check'){$date=$input['date']??date('Y-m-d');if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$date)||$date>date('Y-m-d'))reply(['error'=>'Некорректная дата'],422);$d['checks']=array_values(array_filter($d['checks'],fn($x)=>!($x['user']===$me['id']&&$x['date']===$date)));$d['checks'][]=['user'=>$me['id'],'date'=>$date,'done'=>(bool)($input['done']??false)];}
elseif($action==='metric'){$type=$input['type']??'';$value=(float)($input['value']??0);if(!in_array($type,['steps','weight'],true)||($type==='steps'&&($value<0||$value>100000||floor($value)!=$value))||($type==='weight'&&($value<25||$value>350)))reply(['error'=>'Проверьте значение'],422);$d['metrics'][]=['user'=>$me['id'],'type'=>$type,'value'=>$value,'date'=>date('Y-m-d'),'at'=>date(DATE_ATOM)];}
elseif($action==='user_create'&&$me['role']==='admin'){$login=trim($input['login']??'');$pass=$input['password']??'';if(!preg_match('/^[a-zA-Z0-9_.-]{3,40}$/',$login)||strlen($pass)<8||count(array_filter($d['users'],fn($x)=>$x['login']===$login)))reply(['error'=>'Логин должен быть уникальным (от 3 символов), пароль от 8 символов'],422);$d['users'][]=['id'=>bin2hex(random_bytes(6)),'login'=>$login,'password'=>password_hash($pass,PASSWORD_DEFAULT),'name'=>trim($input['name']??$login),'role'=>'member','team'=>'','goal'=>trim($input['goal']??'Пить 8 стаканов воды'),'chances'=>1];}
elseif($action==='assign'&&$me['role']==='admin'){$ids=array_values(array_filter($d['users'],fn($x)=>$x['role']!=='admin'));usort($ids,fn($a,$b)=>strcmp($a['goal'],$b['goal']));$d['teams']=[];foreach($ids as $i=>$x){$team='Команда №'.(intdiv($i,10)+1);if(!in_array($team,$d['teams']))$d['teams'][]=$team;foreach($d['users'] as &$u)if($u['id']===$x['id'])$u['team']=$team;unset($u);}}
elseif($action==='chances'&&$me['role']==='admin'){$id=$input['id']??'';$n=(int)($input['value']??0);if($n<1||$n>7)reply(['error'=>'Допустимо от 1 до 7'],422);foreach($d['users'] as &$u)if($u['id']===$id&&$u['role']!=='admin')$u['chances']=$n;unset($u);}
elseif($action==='draw'&&$me['role']==='admin'){$d['draw']['finalized']=true;$d['draw']['date']=date(DATE_ATOM);}
elseif($action==='notice'&&$me['role']==='admin'){$text=trim($input['text']??'');if(!$text)reply(['error'=>'Введите текст'],422);array_unshift($d['notices'],['text'=>mb_substr($text,0,500),'date'=>date('d.m.Y')]);}
else reply(['error'=>'Недостаточно прав или неизвестная операция'],403);save($d);reply(view($d));}
header('Content-Type: text/html; charset=utf-8');readfile(__DIR__.'/app.html');
